window.RP_SESSION={"id":"S-3ed9236d410b","messages":[{"id":"RP-II-0086668","time":"2026-04-22T00:59:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"쓰읍.. 아뇨 이게 아닙니다.\n\n마리아 이게 아니에요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086669","time":"2026-04-22T01:01:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"책상 위에 놓여진 종이 위엔 줄 그어진 글자들만 가득했습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086670","time":"2026-04-22T01:09:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"살면서 편지라는건 써본적도 없는걸요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086671","time":"2026-04-22T01:09:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"애초에 글을 쓸 일이..","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086672","time":"2026-04-22T01:09:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"알빠입니까\n적어도 글로 쓰면 머리가 정리된다했기에","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086673","time":"2026-04-22T01:09:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그렇기에 이 글을 씁니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086674","time":"2026-04-22T01:12:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"시작은 간단하게 해봅시다. 내가 어찌 살아왔는지로 시작해봅니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086675","time":"2026-04-22T01:13:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"음...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086676","time":"2026-04-22T01:15:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그때의 '그녀' 는 이름은 없었습니다.\n\n그저 뒷골목에서 살아남는 좀도둑.\n\n어찌 그보다 더 어린시절을 살아왔냐 하면, 알도리가 없다 적어드리겠습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086677","time":"2026-04-22T01:17:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"비밀이냐 물으신다면, 기억에 남지 않았다 말해드립니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086678","time":"2026-04-22T01:18:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"음... 다음은 그이의 이야기를 적어봅니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086679","time":"2026-04-22T01:20:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"아마 그를 마주한 순간부터 '그녀'는 '아나이스' 라 불렸습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086680","time":"2026-04-22T01:22:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"연인이자 아버지였고, 어머니였으며 구원이었다 감히 말할 수 있겠습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086681","time":"2026-04-22T01:24:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"붉고 선명한 눈빛에 이끌렸던 아나이스는 그의 손에서 자랐습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086682","time":"2026-04-22T01:26:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"판단하는 법, 표현하는 법, 살아가는 법.\n\n어느새 모든 게 그와 같아졌습니다.\n\n어쩌면 그이가 꿈꾸던 아이가 되었을지도 모르겠다고. 지금의 나는 생각합니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086683","time":"2026-04-22T01:27:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"뭐, 결국은 과거의 일입니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086684","time":"2026-04-22T01:27:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"하나의 발자취이죠","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086685","time":"2026-04-22T01:27:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그렇게 아나이스는 인생의 목표에서 겨울날 다시 원점으로 복귀합니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086686","time":"2026-04-22T01:28:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이곳에 속한 시점부터, 아나이스는 '마리아'라 불리게 되었습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086687","time":"2026-04-22T01:29:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"어쩌면 어색했습니다.\n\n이 가족에 속하기 시작한 이유는 돈. 그것뿐이었습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086688","time":"2026-04-22T01:30:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"돈과 술","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086689","time":"2026-04-22T01:31:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"무한한 돈과 술","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086690","time":"2026-04-22T01:31:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그걸 꿈꿨습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086691","time":"2026-04-22T01:31:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"불과 몇달전의 마리아는 그것만은 꿈꿨습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086692","time":"2026-04-22T01:32:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"과거를 잡지도 놓지도 못해 허공에 팔만 휘두르던 모습이 아직도 내 눈에 선합니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086693","time":"2026-04-22T01:32:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"당연스럽게도 모두와 벽을 쌓고 지내리라 생각했습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086694","time":"2026-04-22T01:32:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"죽기 전까지 영원토록","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086695","time":"2026-04-22T01:33:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그때의 마리아는 틀렸다고 지금의 마리아는 당당하게 말할 수 있습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086696","time":"2026-04-22T01:34:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이곳에서 의뢰를 다녔습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086697","time":"2026-04-22T01:34:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"죽을 위기 또한 있었습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086698","time":"2026-04-22T01:35:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그렇기에 더 가족같아졌습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086699","time":"2026-04-22T01:38:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"나로 인해 누군가 맘고생을 한다는 것을 깨달았습니다.\n\n내 바늘이 잘못된 곳에 꽂힐지도 모른다는 걸 보았고,\n\n가족이란 별게 없을지도, 누군가에겐 평생의 숙제인 것을 보았습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086700","time":"2026-04-22T01:39:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그동안 보지 못한 모든게 이 짧은 시간 동안 쌓였습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086701","time":"2026-04-22T01:41:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"친구라는 것도 만들어 봤습니다\n\n가져본 적 없지만, 혈육 같은 이들도 생겼습니다\n\n묻지도 따지지도 않고 날 위해주는 사람들을 여럿 보았습니다.\n\n이젠 연인도 생겼습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086702","time":"2026-04-22T01:43:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"내가 그 사람의 사랑을 받아도 될지 확신이 서질 않습니다.\n\n며칠 전, 마리아는 그런 생각을 했습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086703","time":"2026-04-22T01:44:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"연인에게서, 가족에게서 받는 사랑은 같은 것일지 말입니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086704","time":"2026-04-22T01:44:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"다르다면 거기엔 어찌 보답해야 할지 말이에요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086705","time":"2026-04-22T01:45:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그래요, 결론적으로 마리아가 내린 답은 '아니오' 였습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086706","time":"2026-04-22T01:46:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"어딘가.. 달랐습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086707","time":"2026-04-22T01:46:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"정확히는.. 모르겠지만서도요.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086708","time":"2026-04-22T01:47:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"마리아가 사랑을 보답하던 방식은 언제나 그이를 따랐습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086709","time":"2026-04-22T01:49:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"호밀빵 한 조각과 우유 한잔이 전부였습니다.\n\n하지만 가족들은 달랐습니다.\n\n누군가는 따듯한 스튜를 덜어주었고, 다른 누군가는 사과를 하나 내밀기도 했습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086710","time":"2026-04-22T01:50:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그렇기에 마음 먹었습니다.\n\n마리아는 마리아만의 무언가를 대접해보기로요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086711","time":"2026-04-22T01:50:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"결국 이 중구난방 한 이야기는 지금에 도달합니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086712","time":"2026-04-22T01:51:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"촛불 불빛에 시야를 맡겨 글을 써내려가는 '나'입니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086713","time":"2026-04-22T01:51:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"... 고요한 창 밖을 내려다봅니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086714","time":"2026-04-22T01:52:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..벌써 시간이\"","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086715","time":"2026-04-22T01:53:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"펜과 잉크를 한쪽 구석에 몰아두고, 양피지는 둘둘 말아 촛불에 태웁니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086716","time":"2026-04-22T01:53:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"혹여 누가 보고 괜한 걱정을 하면 일이 커질지도 모르거든요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086717","time":"2026-04-22T01:54:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이 글은 나와의 영원한 비밀입니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086718","time":"2026-04-22T01:54:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0086719","time":"2026-04-22T01:54:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
